    /// <summary>
    /// Method to set the METDefault to No for the item barcodes
    /// </summary>
    /// <param name = "_inventItemBarcode">A <t>InventItemBarcode</t> buffer</param>
    public static void METUpdateDefaultForItemBarcode(InventItemBarcode _inventItemBarcode)
    {
        InventItemBarcode   inventItemBarcodeLoc;

        ttsbegin;

        update_recordset inventItemBarcodeLoc
            setting METDefault = NoYes::No
                where inventItemBarcodeLoc.itemId == _inventItemBarcode.itemId
                   && inventItemBarcodeLoc.UnitID == _inventItemBarcode.UnitID
                   && inventItemBarcodeLoc.METVendAccount == _inventitembarcode.METVendAccount //added VM-CB749 Add Vendor filter
                   && inventItemBarcodeLoc.RecId != _inventItemBarcode.RecId;

        ttscommit;
    }

    /// <summary>
    /// Method to find if a default barcode exists for the item Id/unit Id combination
    /// VM-CB749 added Add Vendor filter to existing method
    /// </summary>
    /// <param name = "_itemId">item number</param>
    /// <param name = "_unitId">unit of measure symbol</param>
    /// <returns>true if default barcode found/ else false</returns>
    public static boolean METFindDefaultForItemBarcode(ItemId _itemId, UnitOfMeasureSymbol _unitId,VendAccount _vendAccount)
    {
        boolean             isFound;
        InventItemBarcode   inventItemBarcodeLoc;

        select firstonly METDefault from inventItemBarcodeLoc
            where inventItemBarcodeLoc.itemId == _itemId
               && inventItemBarcodeLoc.UnitID == _unitId
               && (inventItemBarcodeLoc.METVendAccount == _vendAccount)// VM-CB749 added Add Vendor filter to existing method
               && inventItemBarcodeLoc.METDefault == NoYes::Yes;

        if(inventItemBarcodeLoc.METDefault)
        {
            isFound = true;
        }

        return isFound;
    }

